const D = { energy:.6, scale:1, density:.5, speed:1, hue:36, x:.5, y:.82, rise:.85, style:'stone', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };

// ---- real-time walk down the nave; bay content keyed on ABSOLUTE index ------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z = (S.z||0) + dt * P.speed * (.13 + .16*K.intensity) * (.65 + .5*P.energy);
const trav = S.z - Math.floor(S.z), zbase = Math.floor(S.z);

const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
const glow = (.40 + .60*P.energy)*(.55 + .5*K.intensity) + bass*.3;
// incommensurate camera sway + a light that crawls the vault, never re-aligning
const swx = .55*Math.sin(K.t*.083) + .30*Math.sin(K.t*.211+1.6) + .16*Math.sin(K.t*.487+.3);
const swy = .50*Math.sin(K.t*.127+2.2) + .28*Math.sin(K.t*.353+.7);
const lz = S.z + 2.4 + 2.0*Math.sin(K.t*.101) + 1.0*Math.sin(K.t*.257+1.9) + .6*Math.sin(K.t*.613);
const lx = .70*Math.sin(K.t*.067) + .30*Math.sin(K.t*.179+1.2);

const VPX = cl(P.x,.15,.85)*width  + u*.035*P.energy*swx;
const VPY = cl(P.y,.45,1.05)*height + u*.022*P.energy*swy;
const f = u*1.0;
// `scale` widens the NAVE only (Z spacing fixed) so the poke is never a no-op
const RW = u*.46*cl(P.scale,.3,2.4);
const RISE = RW*cl(P.rise,.25,1.4);
const CH = u*.30;                       // springing height above eye
const SP = u*.86, ZMIN = SP*.16;
const NB = Math.round(5 + P.density*6);
const H = ((P.hue%360)+360)%360;
const sty = P.style;
const bp = (sty==='blueprint'), paper = (sty==='engraving'), dark = (sty==='chiaroscuro'), poly = (sty==='polychrome');

const PX = (x,z) => VPX + f*x/z;
const PY = (y,z) => VPY + f*y/z;
const hOf = (xa,dz) => { const m = Math.min(xa*xa, dz*dz); return -(CH + RISE*Math.sqrt(Math.max(0,1-m))); };

// ---- ground -----------------------------------------------------------------
let gc = [H, 12, 8];
if (bp) gc = [212, 62, 20]; else if (paper) gc = [40, 9, 85];
else if (dark) gc = [H, 30, 4]; else if (poly) gc = [18, 30, 12];
noStroke(); fill(gc[0], gc[1], gc[2], 100); rect(0,0,width,height);

function ink(a, w){
  if (bp) stroke(190, 30, 100, a);
  else if (paper) stroke(28, 26, 14, a);
  else if (dark) stroke(H, 16, 96, a);
  else if (poly) stroke(20, 40, 12, a);
  else stroke(H, 10, 92, a);
  strokeWeight(Math.max(.8, w));
}
// cell tone. cell 0=E 1=W 2=N 3=S
function cellTone(cell, bi, near, lit){
  const tv = fr(bi*4.7 + cell*.37);
  const face = (cell===0) ? (.72 + .28*lx) : (cell===1) ? (.72 - .28*lx) : .40;
  const v = (.18 + .70*lit*face + .10*tv) * (.5 + .5*near);
  if (bp)    return [212, 58, cl(12 + 16*v, 8, 34)];
  if (paper) return [40, 7, cl(93 - 42*(1-v), 40, 96)];
  if (dark)  return [H, cl(26 - 14*lit, 3, 36), cl(2 + 46*v*v*1.5, 1, 66)];
  if (poly){ const hh = [8, 210, 44, 150][cell];
             return [hh, cl(52 + 16*tv, 20, 84), cl(20 + 54*v, 10, 82)]; }
  return [H, cl(8 + 9*tv, 2, 22), cl(8 + 74*v, 4, 88)];   // stone
}

// severy boundary in (xa,dz) plan coords, cell 0=E 1=W 2=N 3=S
function severy(cell){
  const pts = [];
  const N1 = 11, N2 = 7;
  if (cell===0 || cell===1){
    const sx = cell===0 ? 1 : -1;
    for (let i=0;i<=N1;i++){ const s=i/N1; pts.push([sx, -1 + 2*s]); }       // wall arch
    for (let i=1;i<=N2;i++){ const s=i/N2; pts.push([sx*(1-s), 1-s]); }      // diagonal in
    for (let i=1;i<=N2;i++){ const s=i/N2; pts.push([sx*s, -s]); }           // diagonal out
  } else {
    const sz = cell===2 ? -1 : 1;
    for (let i=0;i<=N1;i++){ const s=i/N1; pts.push([-1 + 2*s, sz]); }       // transverse arch
    for (let i=1;i<=N2;i++){ const s=i/N2; pts.push([1-s, sz*(1-s)]); }
    for (let i=1;i<=N2;i++){ const s=i/N2; pts.push([-s, sz*s]); }
  }
  return pts;
}
const SEV = [severy(0), severy(1), severy(2), severy(3)];

// stroke an arc/rib sampled along a (xa,dz) path within the bay centred at zc
function arc3(zc, fnc, n, w, a){
  ink(a, w); noFill(); beginShape();
  for (let i=0;i<=n;i++){ const s=i/n, p2=fnc(s), z=Math.max(zc + p2[1]*SP*.5, ZMIN);
    vertex(PX(p2[0]*RW, z), PY(hOf(p2[0],p2[1]), z)); }
  endShape();
}

// ---- bays, far -> near ------------------------------------------------------
for (let k = NB-1; k >= 0; k--){
  const zc0 = (k + .5 - trav)*SP;
  if (zc0 + SP*.5 <= ZMIN) continue;
  const bi = zbase + k;
  const near = cl(1 - k/NB, 0, 1);
  const pd = bi - lz;
  const lit = cl(.16 + .84*Math.exp(-pd*pd*.34), 0, 1) * (.45 + .55*glow);
  const zOf = dz => Math.max(zc0 + dz*SP*.5, ZMIN);

  // side walls dropping away below the springing (frames the vault, kills dead space)
  if (!bp){
    const zn = Math.max(zc0 - SP*.5, ZMIN), zf = zc0 + SP*.5;
    const wc = cellTone(2, bi, near, lit*.5);
    noStroke(); fill(wc[0], wc[1], cl(wc[2]*.5, 1, 60), 100);
    for (let sx=-1; sx<=1; sx+=2){
      quad(PX(sx*RW,zf), PY(-CH,zf), PX(sx*RW,zf), PY(u*4,zf), PX(sx*RW,zn), PY(u*4,zn), PX(sx*RW,zn), PY(-CH,zn));
    }
    // clerestory light behind the lateral cells
    const win = fr(bi*9.1) > .12;
    if (win && !paper){
      push(); blendMode(ADD); noStroke();
      const fl = .55 + .45*Math.sin(K.t*.31 + bi*1.7);
      for (let sx=-1; sx<=1; sx+=2){
        const wz = zc0, wy = -(CH + RISE*.34);
        fill(poly?46:H, poly?60:30, 100, cl(3 + 8*glow*fl, 0, 16));
        ellipse(PX(sx*RW*.92, wz), PY(wy, wz), f*RW*.55/wz, f*RISE*.9/wz);
      }
      pop(); blendMode(BLEND);
    }
  }

  // the four severies
  for (let cell=0; cell<4; cell++){
    const c = cellTone(cell, bi, near, lit);
    const pts = SEV[cell];
    if (!bp && !dark){
      noStroke(); fill(c[0], c[1], c[2], 100);
      beginShape();
      for (let i=0;i<pts.length;i++){ const xa=pts[i][0], dz=pts[i][1], z=zOf(dz);
        vertex(PX(xa*RW, z), PY(hOf(xa,dz), z)); }
      endShape(CLOSE);
    }
    // ashlar courses / hatching across the cell (texture, near bays only)
    if (k < 3 && !dark){
      const nh = paper ? Math.round(1 + 5*cl(1-(c[2]-40)/56,0,1)) : (bp ? 3 : 4);
      ink(paper?30:(bp?42:16), u*.0012); noFill();
      for (let i=1;i<=nh;i++){ const q = i/(nh+1);
        beginShape();
        for (let j=0;j<=10;j++){ const s=j/10;
          let xa, dz;
          if (cell<2){ const sx = cell===0?1:-1; dz = -1 + 2*s; xa = sx*(Math.abs(dz) + (1-Math.abs(dz))*(1-q*.92)); }
          else { const sz = cell===2?-1:1; xa = -1 + 2*s; dz = sz*(Math.abs(xa) + (1-Math.abs(xa))*(1-q*.92)); }
          const z = zOf(dz); vertex(PX(xa*RW, z), PY(hOf(xa,dz), z));
        }
        endShape();
      }
    }
  }

  // ---- ribs: two diagonals, the transverse arch, two wall arches ------------
  const rw2 = Math.max(1.2, u*.0075*cl(near+.3,0,1.3)*(.6+.5*cl(P.scale,.3,2.4)/1.4));
  const rl = cl((dark?.30:.24) + (dark?.70:.62)*lit*glow, 0, 1);
  const ra = cl(100*rl, 8, 100);
  arc3(zc0, s => [-1 + 2*s, -1 + 2*s], 14, rw2, ra);      // diagonal rib
  arc3(zc0, s => [-1 + 2*s,  1 - 2*s], 14, rw2, ra);      // diagonal rib
  arc3(zc0, s => [-1 + 2*s, -1], 12, rw2*1.15, ra);       // transverse arch
  arc3(zc0, s => [ 1, -1 + 2*s], 12, rw2*.8, ra*.85);     // wall arch +x
  arc3(zc0, s => [-1, -1 + 2*s], 12, rw2*.8, ra*.85);     // wall arch -x

  // boss at the crown — a small carved knot, seeded per bay
  const zb = zOf(0), bs = f*RW*.07/zb;
  if (bs > 1.4){
    const bh = 4 + Math.floor(fr(bi*13.3)*4);
    if (dark || bp){ ink(cl(ra*1.1,8,100), rw2*.7); noFill(); }
    else { noStroke(); fill(poly?46:H, poly?55:cl(14,0,60), cl(20 + 62*rl, 6, 94), 100); }
    beginShape();
    for (let i=0;i<bh*2;i++){ const a2 = i/(bh*2)*Math.PI*2 + K.t*.05 + bi;
      const q = (i%2) ? 1 : .5;
      vertex(PX(0,zb) + Math.cos(a2)*bs*q*1.2, PY(hOf(0,0), zb) + Math.sin(a2)*bs*q); }
    endShape(CLOSE);
  }
}

// ---- soft haze in the vault, and the light pool ----------------------------
if (!bp && !paper){
  push(); blendMode(ADD); noStroke();
  const zg = Math.max((lz - S.z)*SP, SP*.4);
  for (let i=4;i>=1;i--){
    fill(poly?46:H, poly?45:26, 100, 1.6 + 2.6*glow);
    ellipse(PX(lx*RW*.5, zg), PY(-(CH+RISE*.7), zg), f*RW*(.5+.30*i)/zg, f*RISE*(.5+.30*i)/zg);
  }
  pop(); blendMode(BLEND);
}
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
